<?php
namespace ADMIN\AdminBundle\Entity;
use Doctrine\ORM\EntityRepository;use Doctrine\ORM\Query\ResultSetMapping;
class ConsultaPersonaObservadaRepository extends EntityRepository{    public function getByFilter($filter){                        $sSql = "SELECT a FROM ADMINAdminBundle:ConsultaPersonaObservada a LEFT JOIN a.iaId i LEFT JOIN a.personaObservada p WHERE 1=1";                if(!empty($filter["fPersonaObservada"])){            $sSql .= " and p.id = ".$filter["fPersonaObservada"];        }                if(!empty($filter["fDesde"])){            $sSql .= " and i.iaTimestamp > to_date( '".$filter["fDesde"]."', 'DD/MM/YYYY HH24:MI:SS' )";        }                if(!empty($filter["fHasta"])){            $sSql .= " and i.iaTimestamp <= to_date( '".$filter["fHasta"]."', 'DD/MM/YYYY HH24:MI:SS' )";        }                if(!empty($filter["fEstado"])){            $sSql .= " and a.estado = '".$filter["fEstado"]."'";        }                if(!empty($filter["fDependencia"])){            $sSql .= " and p.dependencia = ".$filter["fDependencia"];        }                $sSql .= " ORDER BY a.id DESC";        $query = $this->getEntityManager()->createQuery($sSql);                return $query;            }        public function leerPersonasInterpolLog(){        $sql = "CALL persona_observada.verificarPersonas(:salida,:positivos)";        $stmt = $this->getEntityManager()->getConnection()->prepare($sql);        $stmt->bindParam(':salida', $salida, \PDO::PARAM_INPUT_OUTPUT, 4000);        $stmt->bindParam(':positivos', $positivos, \PDO::PARAM_INPUT_OUTPUT, 4000);                $stmt->execute();        $stmt->closeCursor();                        $respuesta = array();                $respuesta['salida'] = $salida;        $respuesta['positivos'] = $positivos;                return $respuesta;    }        
}
